-- Sprint 63: canonical tenant-scoped knowledge and documentation platform.
create table if not exists public.knowledge_articles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,title text not null,slug text not null,summary text not null default'',content text not null,category text not null,tags text[]not null default'{}',status text not null default'draft'check(status in('draft','published','archived')),version integer not null default 1,author_id uuid references auth.users(id),author_name text not null,last_reviewed_at timestamptz,view_count integer not null default 0,helpful_count integer not null default 0,not_helpful_count integer not null default 0,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(workspace_id,slug,version));
create table if not exists public.knowledge_article_versions(id uuid primary key default gen_random_uuid(),article_id uuid not null references public.knowledge_articles(id)on delete cascade,organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,version integer not null,title text not null,summary text not null,content text not null,tags text[]not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(article_id,version));
create table if not exists public.knowledge_documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,file_name text not null,storage_path text not null,mime_type text not null,category text not null,tags text[]not null default'{}',status text not null default'draft'check(status in('draft','published','archived')),version integer not null default 1,author_id uuid references auth.users(id),author_name text not null,last_reviewed_at timestamptz,created_at timestamptz not null default now(),deleted_at timestamptz,unique(workspace_id,storage_path));
create table if not exists public.knowledge_analytics(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,user_id uuid references auth.users(id),event_type text not null check(event_type in('search','search_failed','view','ai_help','feedback_helpful','feedback_not_helpful','upload','support_escalation')),article_id uuid references public.knowledge_articles(id)on delete set null,query text,latency_ms integer,success boolean,metadata jsonb not null default'{}',created_at timestamptz not null default now());
create index if not exists knowledge_articles_search_idx on public.knowledge_articles using gin(to_tsvector('english',title||' '||summary||' '||content));create index if not exists knowledge_articles_tags_idx on public.knowledge_articles using gin(tags);create index if not exists knowledge_analytics_dashboard_idx on public.knowledge_analytics(organization_id,workspace_id,event_type,created_at desc);
alter table public.knowledge_articles enable row level security;alter table public.knowledge_article_versions enable row level security;alter table public.knowledge_documents enable row level security;alter table public.knowledge_analytics enable row level security;
create policy "knowledge articles tenant read"on public.knowledge_articles for select to authenticated using(public.current_workspace_role(workspace_id)is not null);create policy "knowledge versions tenant read"on public.knowledge_article_versions for select to authenticated using(public.current_workspace_role(workspace_id)is not null);create policy "knowledge documents tenant read"on public.knowledge_documents for select to authenticated using(public.current_workspace_role(workspace_id)is not null);create policy "knowledge analytics admin read"on public.knowledge_analytics for select to authenticated using(public.current_workspace_role(workspace_id)in('organization_owner','organization_admin','manager'));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('knowledge-documents','knowledge-documents',false,20971520,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/markdown','text/plain'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "knowledge object tenant insert"on storage.objects for insert to authenticated with check(bucket_id='knowledge-documents'and public.current_workspace_role((storage.foldername(name))[2]::uuid)in('organization_owner','organization_admin','manager'));
create policy "knowledge object tenant read"on storage.objects for select to authenticated using(bucket_id='knowledge-documents'and public.current_workspace_role((storage.foldername(name))[2]::uuid)is not null);
create or replace function public.can_manage_knowledge(p_workspace_id uuid)returns boolean language sql stable security definer set search_path=public as $$select public.current_workspace_role(p_workspace_id)in('organization_owner','organization_admin','manager')$$;
create or replace function public.register_knowledge_document(p_workspace_id uuid,p_file_name text,p_storage_path text,p_mime_type text,p_category text,p_tags text[])returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_id uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or not can_manage_knowledge(p_workspace_id)then raise exception'insufficient knowledge permission';end if;if p_mime_type not in('application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/markdown','text/plain')then raise exception'unsupported document type';end if;insert into knowledge_documents(organization_id,workspace_id,file_name,storage_path,mime_type,category,tags,author_id,author_name)values(v_org,p_workspace_id,p_file_name,p_storage_path,p_mime_type,p_category,coalesce(p_tags,'{}'),auth.uid(),coalesce(auth.jwt()->>'email','Workspace author'))returning id into v_id;insert into knowledge_analytics(organization_id,workspace_id,user_id,event_type,success,metadata)values(v_org,p_workspace_id,auth.uid(),'upload',true,jsonb_build_object('document_id',v_id,'mime_type',p_mime_type));insert into organization_audit_events(organization_id,workspace_id,actor_id,event_type,subject_id)values(v_org,p_workspace_id,auth.uid(),'knowledge.document_uploaded',v_id);return v_id;end$$;
create or replace function public.search_enterprise_knowledge(p_workspace_id uuid,p_query text,p_category text default null,p_tags text[]default'{}',p_limit integer default 30)returns table(id uuid,title text,summary text,category text,tags text[],score real,source text,citation text)language plpgsql security definer set search_path=public as $$declare v_org uuid;v_started timestamptz:=clock_timestamp();v_count integer;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null then raise exception'workspace access required';end if;return query select a.id,a.title,a.summary,a.category,a.tags,ts_rank(to_tsvector('english',a.title||' '||a.summary||' '||a.content),websearch_to_tsquery('english',p_query))::real,'article',a.slug||'@v'||a.version from knowledge_articles a where a.organization_id=v_org and a.workspace_id=p_workspace_id and a.status='published'and a.deleted_at is null and(p_category is null or a.category=p_category)and(cardinality(p_tags)=0 or a.tags@>p_tags)and to_tsvector('english',a.title||' '||a.summary||' '||a.content)@@websearch_to_tsquery('english',p_query)order by 6 desc limit least(greatest(p_limit,1),100);get diagnostics v_count=row_count;insert into knowledge_analytics(organization_id,workspace_id,user_id,event_type,query,latency_ms,success)values(v_org,p_workspace_id,auth.uid(),case when v_count=0 then'search_failed'else'search'end,p_query,(extract(epoch from(clock_timestamp()-v_started))*1000)::integer,v_count>0);end$$;
create or replace function public.record_knowledge_feedback(p_workspace_id uuid,p_article_id uuid,p_helpful boolean)returns void language plpgsql security definer set search_path=public as $$declare a knowledge_articles%rowtype;begin select*into a from knowledge_articles where id=p_article_id and workspace_id=p_workspace_id and public.current_workspace_role(workspace_id)is not null;if not found then raise exception'article unavailable';end if;update knowledge_articles set helpful_count=helpful_count+case when p_helpful then 1 else 0 end,not_helpful_count=not_helpful_count+case when p_helpful then 0 else 1 end where id=a.id;insert into knowledge_analytics(organization_id,workspace_id,user_id,event_type,article_id,success)values(a.organization_id,a.workspace_id,auth.uid(),case when p_helpful then'feedback_helpful'else'feedback_not_helpful'end,a.id,true);end$$;
create or replace function public.enterprise_knowledge_dashboard(p_workspace_id uuid)returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('published_articles',count(*)filter(where status='published'),'drafts',count(*)filter(where status='draft'),'popular_articles',count(*)filter(where view_count>=10),'failed_searches',(select count(*)from knowledge_analytics where workspace_id=p_workspace_id and event_type='search_failed'),'ai_help_requests',(select count(*)from knowledge_analytics where workspace_id=p_workspace_id and event_type='ai_help'),'missing_content',(select count(*)from knowledge_analytics where workspace_id=p_workspace_id and event_type='search_failed'),'document_uploads',(select count(*)from knowledge_documents where workspace_id=p_workspace_id and deleted_at is null),'review_reminders',count(*)filter(where last_reviewed_at is null or last_reviewed_at<now()-interval'180 days'))from knowledge_articles where workspace_id=p_workspace_id and deleted_at is null and public.current_workspace_role(p_workspace_id)is not null$$;
revoke all on function public.register_knowledge_document(uuid,text,text,text,text,text[]),public.search_enterprise_knowledge(uuid,text,text,text[],integer),public.record_knowledge_feedback(uuid,uuid,boolean),public.enterprise_knowledge_dashboard(uuid)from public;grant execute on function public.register_knowledge_document(uuid,text,text,text,text,text[]),public.search_enterprise_knowledge(uuid,text,text,text[],integer),public.record_knowledge_feedback(uuid,uuid,boolean),public.enterprise_knowledge_dashboard(uuid)to authenticated;
